/**
 * @method
 * @name scwin.grd_resultList_fmt_invstDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_resultList_fmt_invstDd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "bzProcsNo") ?? '') : '');
        if (v !== 'SUMPART') { return String((dl && dl.getCellData ? dl.getCellData(r, "invstDd") : '') ?? ''); }
        if (v === 'SUMPART') { return "소계"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.invstDd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.loadCapital
 * @author Inswave
 * @date 2026. 09. 29
 * @param bzProcsNo clmInstSeq comNm invstChgTpCd invstDd invstSaleShrs pershrInvstSaleAmt stkNm incdecRsn
 * @returns
 * @hidden N
*/
scwin.loadCapital = function (bzProcsNo, clmInstSeq, comNm, invstChgTpCd, invstDd, invstSaleShrs, pershrInvstSaleAmt, stkNm, incdecRsn) {
    /* sdd-asis-lifecycle:begin fn_LoadCapital — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent('dma_RegisterReq').set('clmInstSeq', clmInstSeq);
    $c.util.getComponent('ipt_comNm').setValue(comNm);
    (($c.util.getComponent('slc_invstChgTpCd'))?.setValue?.(invstChgTpCd));
    $c.util.getComponent('cal_invstDd').setValue($c.date.dateUnFormat(invstDd));
    $c.util.getComponent('ipt_invstSaleShrs').setValue($c.num.formatNumber(invstSaleShrs));
    $c.util.getComponent('ipt_pershrInvstSaleAmt').setValue($c.num.formatNumber(pershrInvstSaleAmt));
    (($c.util.getComponent('slc_stkNm'))?.setValue?.(stkNm));
    (($c.util.getComponent('slc_incdecRsn'))?.setValue?.(incdecRsn));
    scwin.onloadDataSet();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.vailidationLn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.vailidationLn = async function () {
    /* sdd-asis-lifecycle:begin fn_Vailidation_ln — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_comNm').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm').getValue())) === '') {
        await $c.win.alert("회사명을 입력하십시요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if ($c.util.getComponent('cal_invstDd').getValue().length != 8) {
        await $c.win.alert("투자/매각일을 정확히 입력해주십시요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if (($c.util.getComponent('ipt_invstSaleShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_invstSaleShrs').getValue())) === '') {
        await $c.win.alert("주식수를 입력하세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if (($c.util.getComponent('ipt_pershrInvstSaleAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_pershrInvstSaleAmt').getValue())) === '') {
        await $c.win.alert("주당투자금액을 입력하세요.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if (!await (async () => { const vars = scwin.maxLenCheckVars || []; const names =  scwin.maxLenCheckNames || []; const maxes =  scwin.maxLenCheckMax || []; for (let i = 0; i < vars.length; i++) { const c = $c.util.getComponent(vars[i]); if (!c || !c.getValue) { continue; } const len = $c.str.getByteLength(String(c.getValue() ?? "")); const max = Number(maxes[i]) || 0; if (max && len > max) { await $c.win.alert(String(names[i]) + "의 최대길이(" + max + ")를 \n" + (len - max) + " Byte 만큼 초과하였습니다.\n수정후 저장하세요"); if (c.setFocus) { c.setFocus(); } return false; } } return true; })()) {
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


